import { resolveCanonicalSpeciesName } from './rosterSpeciesAliases.ts';

export type WildEncounterEntry = {
    name: string;
    weight: number | string;
    excludeFromZoneMastery?: boolean;
};

export type ZonePokemonPoolEntry = {
    name: string;
    weight: number;
    excludeFromZoneMastery?: boolean;
};

const WILD_SPECIES_ALIASES: Readonly<Record<string, string>> = {
    'Basculin Blue Striped': 'Basculin',
    'Basculin Red Striped': 'Basculin',
};

const ROSTER_FORM_SUFFIXES: readonly string[] = [
    ' Blue Striped',
    ' Red Striped',
    ' Male',
    ' Female',
    ' Solo',
    ' Alola',
    ' Midday',
    ' Midnight',
    ' Pau',
    ' Red Meteor',
    ' Average',
    ' Small',
    ' Large',
    ' Super',
];

const ROSTER_SPECIES_SPECIAL_KEYS: Readonly<Record<string, string>> = {
    'Jangmo O': 'Jangmo-o',
};

/** Map encounter form names to canonical roster keys (zone pool weight merge). */
export function canonicalizeWildSpeciesName(name: string): string {
    return WILD_SPECIES_ALIASES[name] ?? name;
}

/**
 * Resolve encounter display names to roster keys used by stats, types, and pools.
 * Does not mutate creature.name — sprites and zone mastery keep the form label.
 */
export function resolveRosterSpeciesKey(name: string): string {
    const raw = String(name || '').trim();
    if (!raw) return raw;

    const aliased = WILD_SPECIES_ALIASES[raw];
    if (aliased) return aliased;

    const special = ROSTER_SPECIES_SPECIAL_KEYS[raw];
    if (special) return special;

    for (const suffix of ROSTER_FORM_SUFFIXES) {
        if (raw.endsWith(suffix)) {
            return resolveCanonicalSpeciesName(raw.slice(0, -suffix.length));
        }
    }

    return resolveCanonicalSpeciesName(raw);
}

/** Normalize encounter rows and merge weights when aliases collapse to one species. */
export function mapEncounterEntriesToZonePool(rawList: WildEncounterEntry[]): ZonePokemonPoolEntry[] {
    const byName = new Map<string, ZonePokemonPoolEntry>();

    for (const entry of rawList) {
        if (!entry || typeof entry.name !== 'string') continue;
        const name = canonicalizeWildSpeciesName(entry.name);
        const weight = Math.max(1, Number(entry.weight) || 1);
        const existing = byName.get(name);
        if (existing) {
            existing.weight += weight;
            continue;
        }
        const poolEntry: ZonePokemonPoolEntry = { name, weight };
        if (entry.excludeFromZoneMastery) {
            poolEntry.excludeFromZoneMastery = true;
        }
        byName.set(name, poolEntry);
    }

    return Array.from(byName.values());
}
