import { POKEMON_SPRITE_IDS as _POKEMON_SPRITE_IDS } from '../../constants/balance/dexAndCapture.ts';
import { ENCOUNTER_SPRITE_IDS as _ENCOUNTER_SPRITE_IDS } from '../../constants/balance/encounterSpriteIds.ts';
import {
  MEGA_SPRITE_IDS as _MEGA_SPRITE_IDS,
  MEGA_SPRITE_IDS_NO_SHINY_BACK,
  MEGA_FORM_BASE_SPECIES as _MEGA_FORM_BASE_SPECIES,
} from '../../constants/balance/megaEvolution.ts';

const POKEMON_SPRITE_IDS = _POKEMON_SPRITE_IDS as Record<string, number>;
const ENCOUNTER_SPRITE_IDS = _ENCOUNTER_SPRITE_IDS as Record<string, number>;
const MEGA_SPRITE_IDS = _MEGA_SPRITE_IDS;
const MEGA_FORM_BASE_SPECIES = _MEGA_FORM_BASE_SPECIES;

/**
 * Card sprite URLs — typed subset for snapshots (strict-index safe).
 * Decoupled from src/ui/utils.ts so utils can migrate to ESM constants without
 * pulling constants/core into strict-index-lib via creatureCardSnapshot.
 */

/** Gen V Black/White — PNG + GIF base URLs. */
export const GEN5_BW_SPRITE_BASE =
  'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-v/black-white';

export const GEN5_BW_ANIMATED_BASE = `${GEN5_BW_SPRITE_BASE}/animated`;

/** Last national dex id with Gen V Black/White sprites on PokeAPI (incl. animated GIFs). */
export const GEN5_BW_MAX_DEX_ID = 649;

const LEGACY_SPRITE_BASE =
  'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon';

export const GEN5_SUBSTITUTE_SPRITE = `${GEN5_BW_SPRITE_BASE}/substitute.png`;

export type CardSpriteAnimatedConfig = {
  active?: boolean;
  team?: boolean;
  pension?: boolean;
  all?: boolean;
};

/** Where a card/combat sprite is rendered — drives animatedSprites.* gates. */
export type SpriteRenderContext = 'active' | 'team' | 'pension' | 'storage' | null;

export type CardSpriteResolveOpts = {
  context?: SpriteRenderContext;
  animatedConfig?: CardSpriteAnimatedConfig | null;
};

let spriteRenderContext: SpriteRenderContext = null;

/** Optional fallback when callers omit `spriteOpts.context` (prefer explicit opts). */
export function setSpriteRenderContext(ctx: SpriteRenderContext): void {
  spriteRenderContext = ctx;
}

export function clearSpriteRenderContext(): void {
  spriteRenderContext = null;
}

/** Gen V animated GIF URL → static PNG. Returns null if not an animated URL. */
export function getStaticFallbackFromAnimatedUrl(url: string): string | null {
  if (!url || typeof url !== 'string') return null;
  if (!url.includes('/animated/')) return null;
  return url.replace('/animated/', '/').replace(/\.gif(\?.*)?$/i, '.png$1');
}

function buildGen5Subpath(back: boolean, shiny: boolean): string {
  if (back && shiny) return '/back/shiny';
  if (back) return '/back';
  if (shiny) return '/shiny';
  return '';
}

function buildGen5SpriteUrl(
  base: string,
  key: string | number,
  ext: string,
  back: boolean,
  shiny: boolean,
): string {
  return `${base}${buildGen5Subpath(back, shiny)}/${key}.${ext}`;
}

function buildLegacySpriteUrl(key: string | number, back: boolean, shiny: boolean): string {
  const legacyShiny = shiny ? '/shiny' : '';
  const legacyBack = back ? '/back' : '';
  return `${LEGACY_SPRITE_BASE}${legacyBack}${legacyShiny}/${key}.png`;
}

/** Gen V BW assets exist only for dex 1–649; megas keep custom Gen V paths. */
export function canUseGen5BwSprite(key: string | number, isMega: boolean): boolean {
  if (isMega) return true;
  if (typeof key !== 'number') return false;
  return key >= 1 && key <= GEN5_BW_MAX_DEX_ID;
}

function resolveNidoranDexId(name: string, cleanName: string): number | null {
  const lowerName = name.toLowerCase();
  const lowerClean = cleanName.toLowerCase();
  if (!lowerName.includes('nidoran') && !lowerClean.startsWith('nidoran')) {
    return null;
  }
  if (
    lowerClean === 'nidorina' ||
    lowerClean === 'nidoqueen' ||
    lowerClean === 'nidorino' ||
    lowerClean === 'nidoking'
  ) {
    return null;
  }
  const isFemale =
    lowerClean.includes('-f') ||
    name.includes('\u2640') ||
    name.includes('♀') ||
    /\u2640/.test(name);
  const isMale =
    lowerClean.includes('-m') ||
    name.includes('\u2642') ||
    name.includes('♂') ||
    /\u2642/.test(name);
  if (isFemale && !isMale) return 29;
  if (isMale && !isFemale) return 32;
  if (lowerClean === 'nidoran' || lowerClean === 'nidoran-m') return 32;
  if (lowerClean === 'nidoran-f') return 29;
  if (lowerClean.startsWith('nidoran')) return 32;
  return null;
}

function resolveSpriteFileKey(
  name: string,
  cleanName: string,
): { key: string | number; isMega: boolean; isNameKey?: boolean } {
  if (Object.prototype.hasOwnProperty.call(MEGA_SPRITE_IDS, name)) {
    const key = MEGA_SPRITE_IDS[name];
    if (key !== undefined) return { key, isMega: true };
  }
  if (Object.prototype.hasOwnProperty.call(MEGA_FORM_BASE_SPECIES, name)) {
    const baseSpecies = MEGA_FORM_BASE_SPECIES[name];
    if (baseSpecies && Object.prototype.hasOwnProperty.call(POKEMON_SPRITE_IDS, baseSpecies)) {
      const baseKey = POKEMON_SPRITE_IDS[baseSpecies];
      if (baseKey !== undefined) return { key: baseKey, isMega: false };
    }
  }
  const nidoranId = resolveNidoranDexId(name, cleanName);
  if (nidoranId !== null) {
    return { key: nidoranId, isMega: false };
  }
  if (Object.prototype.hasOwnProperty.call(POKEMON_SPRITE_IDS, name)) {
    const key = POKEMON_SPRITE_IDS[name];
    if (key !== undefined) return { key, isMega: false };
  }
  if (Object.prototype.hasOwnProperty.call(ENCOUNTER_SPRITE_IDS, name)) {
    const key = ENCOUNTER_SPRITE_IDS[name];
    if (key !== undefined) return { key, isMega: false };
  }
  return { key: cleanName, isMega: false, isNameKey: true };
}

function normalizePokemonSlug(name: string): string {
  let cleanName = name
    .toLowerCase()
    .replace(/\s+/g, '-')
    .replace('\u2640', '-f')
    .replace('\u2642', '-m')
    .replace('.', '')
    .replace(/['\u2018\u2019]/g, '');

  if (cleanName === 'nidoran') cleanName = 'nidoran-m';
  if (cleanName === 'mr-mime') cleanName = 'mr-mime';
  if (cleanName === 'mime-jr') cleanName = 'mime-jr';
  if (cleanName === 'farfetchd') cleanName = 'farfetchd';
  return cleanName;
}

/**
 * Pokemon sprite URL (PokeAPI Gen V). Mirrors src/ui/utils.ts for card snapshots.
 */
export function getPokemonSpriteUrl(
  name: string,
  shiny: boolean,
  back = false,
  spriteOpts: CardSpriteResolveOpts | null = null,
): string {
  if (!name) {
    return GEN5_SUBSTITUTE_SPRITE;
  }

  const cleanName = normalizePokemonSlug(name);

  const g = globalThis as {
    POKETIME_ANIMATED_SPRITES_CONFIG?: CardSpriteAnimatedConfig;
    MEGA_SPRITE_IDS_NO_SHINY_BACK?: Set<number>;
  };

  const cfg =
    spriteOpts?.animatedConfig != null
      ? spriteOpts.animatedConfig
      : g.POKETIME_ANIMATED_SPRITES_CONFIG;
  const context =
    spriteOpts?.context != null ? spriteOpts.context : spriteRenderContext;

  let animated = false;
  if (cfg) {
    if (cfg.all) animated = true;
    else if (cfg.active && context === 'active') animated = true;
    else if (cfg.team && context === 'team') animated = true;
    else if (cfg.pension && context === 'pension') animated = true;
  }

  const { key, isMega } = resolveSpriteFileKey(name, cleanName);
  let useShiny = !!shiny;
  if (
    isMega &&
    back &&
    useShiny &&
    MEGA_SPRITE_IDS_NO_SHINY_BACK instanceof Set &&
    MEGA_SPRITE_IDS_NO_SHINY_BACK.has(key as number)
  ) {
    useShiny = false;
  }

  const useGen5 = canUseGen5BwSprite(key, isMega);

  if (animated && !isMega && useGen5 && typeof key === 'number') {
    return buildGen5SpriteUrl(GEN5_BW_ANIMATED_BASE, key, 'gif', back, useShiny);
  }

  if (useGen5 && typeof key === 'number') {
    return buildGen5SpriteUrl(GEN5_BW_SPRITE_BASE, key, 'png', back, useShiny);
  }

  const legacyKey = typeof key === 'number' ? key : cleanName;
  return buildLegacySpriteUrl(legacyKey, back, useShiny);
}

/** Fétiche panel showcase — always prefer Gen V animated GIF when available. */
export function feticheShowcaseSpriteUrl(name: string): string {
  if (!name) return '';
  return getPokemonSpriteUrl(name, false, false, {
    animatedConfig: { all: true },
  });
}

/** Capture / Pokédex previews — prefer static PNG over animated GIF. */
export function capturePreviewSpriteUrl(name: string, shiny: boolean): string {
  if (!name) return '';
  const g = globalThis as { POKETIME_ANIMATED_SPRITES_CONFIG?: CardSpriteAnimatedConfig };
  const prevCfg = g.POKETIME_ANIMATED_SPRITES_CONFIG;
  if (prevCfg && typeof prevCfg === 'object') {
    g.POKETIME_ANIMATED_SPRITES_CONFIG = { ...prevCfg, team: false, pension: false, all: false };
  }
  try {
    const url = getPokemonSpriteUrl(name, shiny);
    return getStaticFallbackFromAnimatedUrl(url) ?? url;
  } finally {
    if (prevCfg) g.POKETIME_ANIMATED_SPRITES_CONFIG = prevCfg;
  }
}
