/**
 * Fonction pour obtenir les stats de base d'un Pokémon
 */
/**
 * Fonction pour obtenir les stats de base d'un Pokémon
 * (Mise à jour pour supporter le Spécial)
 */
export function getPokemonBaseStats(name: string, level: number): PokemonBaseStat {
    const levelMultiplier = 1 + (level * 0.1);
    const statsKey = resolveRosterSpeciesKey(name);
    
    // Si le Pokémon a des stats personnalisées, les utiliser
    if (POKEMON_BASE_STATS[statsKey]) {
        const base = POKEMON_BASE_STATS[statsKey];
        
        // Sécurité : Si spattack n'est pas défini dans la liste, on prend l'attaque normale
        const baseSpAtk = base.spattack !== undefined ? base.spattack : base.attack;
        const baseSpDef = base.spdefense !== undefined ? base.spdefense : base.defense;

        return {
            hp: Math.floor(base.hp * 2 * levelMultiplier), // Ton multiplicateur x2 PV
            
            attack: Math.floor(base.attack * levelMultiplier),
            spattack: Math.floor(baseSpAtk * levelMultiplier), // ✅ Ajouté
            
            defense: Math.floor(base.defense * levelMultiplier),
            spdefense: Math.floor(baseSpDef * levelMultiplier), // ✅ Ajouté
            
            speed: Math.floor(base.speed * levelMultiplier)
        };
    }
    
    // Sinon, utiliser des stats génériques basées sur le niveau (Fallback)
    return {
        hp: Math.floor(10 * levelMultiplier),
        attack: Math.floor(1 * levelMultiplier),
        spattack: Math.floor(1 * levelMultiplier), // ✅ Ajouté
        defense: Math.floor(1 * levelMultiplier),
        spdefense: Math.floor(1 * levelMultiplier), // ✅ Ajouté
        speed: Math.floor(1 * levelMultiplier)
    };
}

// NOTE: egg pool enrichment (enrichEggPoolGen5To9ByFamilyRarity) is now called
// from src/main.js after both pokemonStats.js and eggPool.js modules are loaded.
// This breaks the circular dependency between the two modules.

// Legacy scripts / QA tools may still read window.* (D8-11 : plus de pont legacy-bridge-core).
if (typeof window !== 'undefined') {
    window.POKEMON_BASE_STATS = POKEMON_BASE_STATS;
    window.getPokemonBaseStats = getPokemonBaseStats;
}
